def solve(x):
    def dfs(node, visited):
        visited.add(node)
        for neighbor in x["edges"]:
            if neighbor[0] == node:
                dfs(neighbor[1], visited)
            elif neighbor[1] == node:
                dfs(neighbor[0], visited)
        return visited

    visited = set()
    result = dfs(x["start"], visited)
    result.add(x["start"])
    return sorted(result)
